public final class TokenBucketLimiter {
  private final int capacity; private final int refillPerSecond; private final LongSupplier clock;
  private double tokens; private long lastNanos;
  public synchronized boolean tryAcquire() {
    refill();
    if (tokens >= 1) { tokens -= 1; return true; }
    return false;
  }
  private void refill() {
    long now = clock.getAsLong();
    long elapsedMs = (now - lastNanos) / 1_000_000;
    tokens = Math.min(capacity, tokens + (elapsedMs / 1000) * refillPerSecond);
    lastNanos = now;
  }
}

